import{c as i,Q as t,J as o,h as e,k as s,m as n,e as c}from"./chunks/framework.WgZQdPFo.js";const y=JSON.parse('{"title":"Ценообразование, наценка и маржа: как не работать в минус","description":"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор.","frontmatter":{"title":"Ценообразование, наценка и маржа: как не работать в минус","description":"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор.","tags":["Экономика","Инструменты","Мастерская"],"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Ценообразование, наценка и маржа: как не работать в минус"}],["meta",{"property":"og:description","content":"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор."}],["meta",{"property":"og:url","content":"https://omnicraft-erp.com/ru/articles/pricing-and-margins"}],["meta",{"property":"og:image","content":"https://omnicraft-erp.com/img/ru/front/calculator.webp"}],["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@graph\\": [\\n    {\\n      \\"@type\\": \\"WebApplication\\",\\n      \\"name\\": \\"Калькулятор наценки и маржи онлайн\\",\\n      \\"applicationCategory\\": \\"BusinessApplication\\",\\n      \\"operatingSystem\\": \\"All\\",\\n      \\"browserRequirements\\": \\"Requires JavaScript. Requires HTML5.\\",\\n      \\"offers\\": {\\n        \\"@type\\": \\"Offer\\",\\n        \\"price\\": \\"0\\",\\n        \\"priceCurrency\\": \\"RUB\\"\\n      },\\n      \\"description\\": \\"Практический онлайн-калькулятор торговой наценки, валовой маржи и розничной цены изделия от себестоимости для мастерских и штучного производства.\\"\\n    },\\n    {\\n      \\"@type\\": \\"Article\\",\\n      \\"headline\\": \\"Ценообразование, наценка и маржа: как не работать в минус\\",\\n      \\"description\\": \\"Практическое руководство по ценообразованию в штучном производстве. Разница между торговой наценкой и маржой, формулы расчёта розничной цены и онлайн-калькулятор.\\",\\n      \\"image\\": \\"https://omnicraft-erp.com/img/ru/front/calculator.webp\\",\\n      \\"inLanguage\\": \\"ru-RU\\",\\n      \\"mainEntityOfPage\\": \\"https://omnicraft-erp.com/ru/articles/pricing-and-margins\\",\\n      \\"datePublished\\": \\"2026-10-10\\",\\n      \\"dateModified\\": \\"2026-10-24\\",\\n      \\"author\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"ОмниКрафт ЕРП\\",\\n        \\"url\\": \\"https://omnicraft-erp.com/ru/\\"\\n      },\\n      \\"publisher\\": {\\n        \\"@type\\": \\"Organization\\",\\n        \\"name\\": \\"ОмниКрафт ЕРП\\",\\n        \\"logo\\": {\\n          \\"@type\\": \\"ImageObject\\",\\n          \\"url\\": \\"https://omnicraft-erp.com/logo.svg\\"\\n        }\\n      }\\n    },\\n    {\\n      \\"@type\\": \\"BreadcrumbList\\",\\n      \\"itemListElement\\": [\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 1,\\n          \\"name\\": \\"Главная\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/ru/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 2,\\n          \\"name\\": \\"Статьи и руководства\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/ru/articles/\\"\\n        },\\n        {\\n          \\"@type\\": \\"ListItem\\",\\n          \\"position\\": 3,\\n          \\"name\\": \\"Ценообразование, наценка и маржа\\",\\n          \\"item\\": \\"https://omnicraft-erp.com/ru/articles/pricing-and-margins\\"\\n        }\\n      ]\\n    }\\n  ]\\n}\\n"]]},"headers":[],"relativePath":"ru/articles/pricing-and-margins.md","filePath":"ru/articles/pricing-and-margins.md"}'),p={name:"ru/articles/pricing-and-margins.md"},d={class:"interactive-frame-container"};function h(m,a,v,u,g,f){const l=t("MarginCalculator"),r=t("OmniCraftFrame");return o(),e("div",null,[a[0]||(a[0]=s('<div class="article-breadcrumb"><a href="/ru/articles/">← Все статьи и руководства</a></div><h1 id="ценообразование-наценка-и-маржа-как-не-работать-в-минус" tabindex="-1">Ценообразование, наценка и маржа: как не работать в минус <a class="header-anchor" href="#ценообразование-наценка-и-маржа-как-не-работать-в-минус" aria-label="Permalink to &quot;Ценообразование, наценка и маржа: как не работать в минус&quot;">​</a></h1><p>Путаница между <strong>наценкой</strong> и <strong>маржой</strong> — главный финансовый капкан мастерской.</p><p>Мастер считает затраты на кожаное портмоне — вышло <strong>2 000 ₽</strong>. Желая получить 40% прибыли, он добавляет наценку 40% (2 800 ₽). Затем делает скидку 30%, полагая, что 10% остаётся. Итог — чистый убыток: со скидкой цена равна <strong>1 960 ₽</strong>, и мастер доплачивает 40 ₽ за заказ из своего кармана.</p>',4)),n(l,{lang:"ru"}),a[1]||(a[1]=s('<hr><h2 id="наценка-и-маржа-в-чем-принципиальная-разница" tabindex="-1">Наценка и маржа: в чём принципиальная разница? <a class="header-anchor" href="#наценка-и-маржа-в-чем-принципиальная-разница" aria-label="Permalink to &quot;Наценка и маржа: в чём принципиальная разница?&quot;">​</a></h2><p>Многие начинающие предприниматели используют слова «наценка» и «маржа» как синонимы. Это грубая ошибка, приводящая к кассовым разрывам.</p><div class="price-breakdown-card"><div class="breakdown-header"><span class="breakdown-tag">Анатомия розничной цены</span><div class="breakdown-title">Структура выручки: себестоимость, маржа и наценка</div><p class="breakdown-desc">При себестоимости 60% от цены и наценке 66.7% итоговая валовая маржа составляет ровно 40%:</p></div><div class="breakdown-bar-track"><div class="breakdown-segment seg-cost" style="width:60%;background:#64748b;" data-tooltip="Себестоимость: 60% выручки (база 100%)"><span class="seg-label">Себестоимость: 60% выручки (База 100%)</span></div><div class="breakdown-segment seg-margin" style="width:40%;background:#10b981;" data-tooltip="Валовая маржа: 40% (наценка 66.7%)"><span class="seg-label">Валовая маржа: 40% (Наценка 66.7%)</span></div></div></div><div class="craft-metaphor-card"><div class="metaphor-header"><div class="metaphor-badge-row"><span class="metaphor-badge">Каноническая цеховая метафора</span><span class="metaphor-badge-method">Базовая экономика мастерской</span></div><div class="metaphor-title"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="metaphor-icon"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a10 10 0 0 1 10 10H12V2z"></path></svg> «Пирог выручки против фундамента затрат»: почему маржа не бывает больше 100% </div></div><p class="metaphor-story"> Представьте, что <strong>наценка</strong> — это строительный этаж, который вы возводите поверх <em>фундамента себестоимости</em>. Если фундамент стоил 1 000 ₽, вы можете надстроить этаж в 500 ₽ (наценка 50%), в 1 000 ₽ (наценка 100%) или даже в 3 000 ₽ (наценка 300%). Ограничений сверху нет. </p><p class="metaphor-story"> А <strong>маржа</strong> — это <em>кусок уже испечённого пирога выручки</em>, которую вам заплатил клиент. Вся сумма в кассе — это 100% пирога. Один кусок сразу забирает поставщик сырья (себестоимость), а то, что осталось на вашей тарелке — это маржа. Вы физически не можете отрезать кусок пирога больше, чем сам целый пирог: поэтому маржа <strong>никогда не может превысить 100%</strong>. </p><div class="metaphor-math-grid"><div class="metaphor-math-step"><div class="step-label">Фундамент затрат</div><div class="step-val">Себестоимость = <strong>1 000 ₽</strong></div></div><div class="metaphor-math-op">+</div><div class="metaphor-math-step"><div class="step-label">Наценка (+100%)</div><div class="step-val">Добавка = <strong>1 000 ₽</strong></div></div><div class="metaphor-math-op">=</div><div class="metaphor-math-step highlight-step"><div class="step-label">Пирог выручки (Цена)</div><div class="step-val">2 000 ₽ → Маржа = <strong>50%</strong></div></div></div><p class="metaphor-conclusion"> Двойная наценка (х2 к затратам) даёт не 100%, а ровно <strong>50% маржи</strong>. Путая эти базы, мастер ошибочно полагает, что имеет запас прочности в 100%, и разоряется на первой же сезонной распродаже. </p></div><h3 id="_1-торговая-наценка-markup" tabindex="-1">1. Торговая наценка (Markup) <a class="header-anchor" href="#_1-торговая-наценка-markup" aria-label="Permalink to &quot;1. Торговая наценка (Markup)&quot;">​</a></h3><p>Наценка показывает, <strong>на сколько процентов розничная цена выше себестоимости</strong>. Она отталкивается от затрат.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Формула наценки</span><div class="formula-heading">Торговая наценка от себестоимости (Markup %)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Наценка %</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Цена продажи</span> <span class="math-op">−</span> <span class="math-var">Себестоимость</span></span><span class="math-denom"><span class="math-var">Себестоимость</span></span></span><span class="math-op">×</span><span class="math-var">100%</span></div></div></div><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Пределы наценки:</strong> наценка может составлять 50%, 100%, 300% и более. Если чехол для очков обходится в 500 ₽, а продаётся за 1 500 ₽, наценка составляет 200%.</div></li></ul><h3 id="_2-маржинальность-или-маржа-margin" tabindex="-1">2. Маржинальность или маржа (Margin) <a class="header-anchor" href="#_2-маржинальность-или-маржа-margin" aria-label="Permalink to &quot;2. Маржинальность или маржа (Margin)&quot;">​</a></h3><p>Маржа показывает, <strong>какую долю в итоговой выручке составляют «чистые» заработанные деньги</strong>. Она отталкивается от продажной цены.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Формула маржи</span><div class="formula-heading">Валовая маржинальность выручки (Margin %)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Маржа %</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Цена продажи</span> <span class="math-op">−</span> <span class="math-var">Себестоимость</span></span><span class="math-denom"><span class="math-var">Цена продажи</span></span></span><span class="math-op">×</span><span class="math-var">100%</span></div></div></div><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Пределы маржи:</strong> маржа <strong>никогда не может превышать 100%</strong>. Даже при нулевой себестоимости продажа изделия за 2 000 ₽ даёт ровно 100% маржи.</div></li></ul><div class="tip custom-block"><p class="custom-block-title">Цеховой закон: маржа всегда меньше наценки</p><p>При одинаковой сумме прибыли в рублях процент маржи <strong>всегда ниже</strong> процента наценки. Наценка 50% даёт 33.3% маржи, наценка 100% даёт ровно 50% маржи, а наценка 300% — лишь 75% маржи.</p></div><h3 id="сравнительная-таблица-соответствия-наценки-и-маржи" tabindex="-1">Сравнительная таблица соответствия наценки и маржи <a class="header-anchor" href="#сравнительная-таблица-соответствия-наценки-и-маржи" aria-label="Permalink to &quot;Сравнительная таблица соответствия наценки и маржи&quot;">​</a></h3><p>При базовой себестоимости изделия 1 000 ₽:</p><table class="craft-matrix-table"><thead><tr><th style="width:20%;">Себестоимость</th><th style="width:20%;">Целевая маржа</th><th style="width:20%;">Наценка</th><th style="width:20%;">Розничная цена</th><th style="width:20%;">Прибыль</th></tr></thead><tbody><tr><td>1 000 ₽</td><td><strong>20%</strong></td><td>25%</td><td>1 250 ₽</td><td>250 ₽</td></tr><tr><td>1 000 ₽</td><td><strong>30%</strong></td><td>43%</td><td>1 428 ₽</td><td>428 ₽</td></tr><tr><td>1 000 ₽</td><td><strong>40%</strong></td><td>67%</td><td>1 667 ₽</td><td>667 ₽</td></tr><tr><td>1 000 ₽</td><td><strong>50%</strong></td><td>100%</td><td>2 000 ₽</td><td>1 000 ₽</td></tr><tr><td>1 000 ₽</td><td><strong>60%</strong></td><td>150%</td><td>2 500 ₽</td><td>1 500 ₽</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Внимание к опасности слепой скидки</p><p>Если вы хотите получить рентабельность продаж (маржу) 40%, вам необходимо делать наценку на себестоимость <strong>не 40%, а 67%</strong>. Если вы просто нацените 40%, ваша фактическая маржа составит всего 28.5%. Скидка в 30% при такой наценке мгновенно загонит мастерскую в убыток.</p></div><hr><h2 id="как-рассчитать-розничную-цену-зная-себестоимость-и-целевую-маржу" tabindex="-1">Как рассчитать розничную цену, зная себестоимость и целевую маржу <a class="header-anchor" href="#как-рассчитать-розничную-цену-зная-себестоимость-и-целевую-маржу" aria-label="Permalink to &quot;Как рассчитать розничную цену, зная себестоимость и целевую маржу&quot;">​</a></h2><p>Когда мастер определяет продажную стоимость изделия, правильный ход мысли — идти не от наценки, а от <strong>целевой рентабельности</strong>.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Инженерный расчёт</span><div class="formula-heading">Формула розничной цены от целевой маржинальности</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Цена продажи</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Полная себестоимость</span></span><span class="math-denom">1 <span class="math-op">−</span> <span class="math-fraction"><span class="math-num"><span class="math-var">Целевая маржа %</span></span><span class="math-denom">100</span></span></span></span></div></div></div><details class="details custom-block"><summary>Подробный математический вывод формулы розничной цены</summary><ol class="craft-ordered-list"><li><div><strong>Базовое определение:</strong> маржа рассчитывается как доля чистой прибыли в итоговой выручке: Маржа = (Цена − Себестоимость) / Цена.</div></li><li><div><strong>Умножение на Цену:</strong> раскрываем пропорцию: Цена × Маржа = Цена − Себестоимость.</div></li><li><div><strong>Группировка слагаемых:</strong> переносим себестоимость в левую часть: Себестоимость = Цена − (Цена × Маржа) = Цена × (1 − Маржа).</div></li><li><div><strong>Итоговая цена продажи:</strong> выражаем розничную цену через деление: <strong>Цена = Себестоимость / (1 − Маржа)</strong>.</div></li></ol></details><h4 id="пример-из-цеха" tabindex="-1">Пример из цеха: <a class="header-anchor" href="#пример-из-цеха" aria-label="Permalink to &quot;Пример из цеха:&quot;">​</a></h4><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Полная себестоимость ремня:</strong> 2 400 ₽ (кожа чепрак с учётом обрезков + пряжка + 2 часа работы мастера + износ инструмента).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Целевая маржинальность:</strong> 35% (для покрытия аренды мастерской, налогов и инвестиций в развитие).</div></li></ul><div class="formula-hero-card" style="margin:16px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Цена продажи</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">2 400</span><span class="math-denom">1 <span class="math-op">−</span> 0.35</span></span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">2 400</span><span class="math-denom">0.65</span></span><span class="math-op">≈</span><span class="math-var" style="color:#10b981;">3 690 ₽</span></div></div></div><p>Если бы мастер по ошибке просто прибавил 35% к себестоимости, цена составила бы 2 400 × 1.35 = 3 240 ₽. Потеря на каждом ремне составила бы <strong>450 рублей</strong> чистой прибыли.</p><hr><h2 id="три-метода-ценообразования-в-ремесленном-производстве" tabindex="-1">Три метода ценообразования в ремесленном производстве <a class="header-anchor" href="#три-метода-ценообразования-в-ремесленном-производстве" aria-label="Permalink to &quot;Три метода ценообразования в ремесленном производстве&quot;">​</a></h2><p>На практике мастерские используют три базовых подхода к назначению цен:</p><h3 id="_1-затратныи-метод-«себестоимость-плюс»" tabindex="-1">1. Затратный метод («Себестоимость плюс») <a class="header-anchor" href="#_1-затратныи-метод-«себестоимость-плюс»" aria-label="Permalink to &quot;1. Затратный метод («Себестоимость плюс»)&quot;">​</a></h3><p>Классический инженерный подход. Вы суммируете все прямые затраты (материалы, полезный раскрой, фурнитуру), оплату труда мастера за затраченные часы, долю постоянных накладных расходов (аренда помещения, амортизация оборудования, расходники) и закладываете фиксированную норму прибыли.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Главное преимущество:</strong> гарантирует полную окупаемость каждого изделия и защиту от работы в минус при колебаниях цен на сырьё.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Ограничение:</strong> метод не учитывает субъективную ценность авторского дизайна и платежеспособность целевой аудитории.</div></li></ul><h3 id="_2-рыночныи-метод-анализ-конкурентов" tabindex="-1">2. Рыночный метод (Анализ конкурентов) <a class="header-anchor" href="#_2-рыночныи-метод-анализ-конкурентов" aria-label="Permalink to &quot;2. Рыночный метод (Анализ конкурентов)&quot;">​</a></h3><p>Мастер изучает витрины ярмарок, маркетплейсов и социальных сетей других ремесленников схожего уровня и выставляет среднерыночную стоимость.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Цеховой риск:</strong> конкурент может работать дома на старых запасах сырья без учёта стоимости своего труда и амортизации станков. Слепое копирование чужих цен — частая причина скрытого банкротства.</div></li></ul><h3 id="_3-ценностныи-метод-премиальное-ценообразование" tabindex="-1">3. Ценностный метод (Премиальное ценообразование) <a class="header-anchor" href="#_3-ценностныи-метод-премиальное-ценообразование" aria-label="Permalink to &quot;3. Ценностный метод (Премиальное ценообразование)&quot;">​</a></h3><p>Цена определяется не затратами материалов, а эмоциональной ценностью, статусностью, уникальностью ручной работы и качеством сервиса (подарочная упаковка, пожизненная гарантия на швы, индивидуальное тиснение).</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Главное преимущество:</strong> обеспечивает максимальную маржинальность (от 60% до 80%), формируя фонд развития и инвестиций мастерской.</div></li></ul><hr><h2 id="точка-безубыточности-мастерскои" tabindex="-1">Точка безубыточности мастерской <a class="header-anchor" href="#точка-безубыточности-мастерскои" aria-label="Permalink to &quot;Точка безубыточности мастерской&quot;">​</a></h2><p><strong>Точка безубыточности (Break-Even Point)</strong> — это объём продаж, при котором выручка мастерской в точности покрывает все постоянные и переменные расходы. Прибыль в этой точке равна нулю: мастерская не терпит убытков, но ещё ничего не заработала сверх расходов.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Финансовая модель</span><div class="formula-heading">Точка безубыточности мастерской (Break-Even Point)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Точка безубыточности (шт)</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Постоянные расходы в месяц</span></span><span class="math-denom"><span class="math-var">Цена изделия</span> <span class="math-op">−</span> <span class="math-var">Переменная себестоимость</span></span></span></div></div></div><h4 id="пример" tabindex="-1">Пример: <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример:&quot;">​</a></h4><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Постоянные расходы:</strong> 30 000 ₽/мес (аренда мастерской, отопление, связь).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Розничная цена сумки:</strong> 9 000 ₽.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Переменная себестоимость единицы:</strong> 4 000 ₽ (кожа, подклад, нитки, молния, фурнитура).</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Маржинальный доход с одной сумки:</strong> 9 000 − 4 000 = 5 000 ₽.</div></li></ul><div class="formula-hero-card" style="margin:16px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Точка безубыточности</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num">30 000</span><span class="math-denom">5 000</span></span><span class="math-op">=</span><span class="math-var" style="color:#10b981;">6 сумок в месяц</span></div></div></div><p>Первые 6 сумок каждого месяца работают исключительно на покрытие аренды и коммунальных счетов. И только начиная с 7-й сумки мастерская начинает формировать прибыль владельца.</p><div class="tip custom-block"><p class="custom-block-title">Цеховой ориентир: маржа по каналам сбыта</p><ul><li><strong>Оптовые поставки и корпоративные заказы:</strong> здоровая маржа составляет <strong>20–30%</strong> (наценка 25–43%). Окупаемость обеспечивается объёмом партии.</li><li><strong>Прямая розница (ярмарки, сайт, соцсети):</strong> здоровая маржа составляет <strong>40–55%</strong> (наценка 67–122%).</li><li><strong>Маркетплейсы (Ozon, Wildberries):</strong> закладывайте маржу не менее <strong>50–60%</strong>, так как комиссии площадки, логистика и эквайринг съедают до 25% розничной цены.</li></ul></div><hr><h2 id="автоматизация-контроля-себестоимости-и-маржи-на-верстаке" tabindex="-1">Автоматизация контроля себестоимости и маржи на верстаке <a class="header-anchor" href="#автоматизация-контроля-себестоимости-и-маржи-на-верстаке" aria-label="Permalink to &quot;Автоматизация контроля себестоимости и маржи на верстаке&quot;">​</a></h2><p>В условиях реального производства рассчитывать маржу вручную в блокноте для каждого изделия рискованно: цены на сырьё постоянно меняются, а ассортимент растёт.</p><p>Профессиональная система для мастерской связывает технологические карты, складские остатки и розничные цены в единый контур:</p>',52)),c("div",d,[n(r,{screen:"calculator",interactive:"",lang:"ru"})]),a[2]||(a[2]=s('<p>В программе <strong>«ОмниКрафт ЕРП»</strong> калькулятор себестоимости мгновенно показывает реальную рентабельность изделия с учётом обрезков сырья, трудоёмкости и постоянных затрат цеха, не позволяя мастеру выставить убыточную цену.</p><hr><h2 id="часто-задаваемые-вопросы-о-ценообразовании-в-мастерскои" tabindex="-1">Часто задаваемые вопросы о ценообразовании в мастерской <a class="header-anchor" href="#часто-задаваемые-вопросы-о-ценообразовании-в-мастерскои" aria-label="Permalink to &quot;Часто задаваемые вопросы о ценообразовании в мастерской&quot;">​</a></h2><div class="craft-faq-accordion"><details class="faq-item"><summary>Какая маржинальность считается здоровой для штучной мастерской?</summary><div class="faq-content"><p>Для штучного производства и авторских изделий безопасным минимумом в рознице считается маржа <strong>40–50%</strong> (наценка 67–100%). Если ваша маржа опускается ниже 30%, любая сезонная заминка со сбытом, повышение аренды или брак раскроя немедленно приведёт к кассовому разрыву.</p></div></details><details class="faq-item"><summary>Как комиссии маркетплейсов влияют на розничную цену и маржу?</summary><div class="faq-content"><p>Маркетплейсы берут комиссию от <strong>розничной цены продажи</strong>, а не от вашей себестоимости. Если площадка удерживает 20% комиссии, а ваша наценка составляла всего 25% (маржа 20%), вы отдадите маркетплейсу абсолютно всю свою прибыль, оставшись с нулевым заработком.</p><div class="formula-hero-card" style="margin:12px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Цена на маркетплейсе</span><span class="math-op">=</span><span class="math-fraction"><span class="math-num"><span class="math-var">Желаемая цена на руки</span></span><span class="math-denom">1 <span class="math-op">−</span> <span class="math-fraction"><span class="math-num"><span class="math-var">Комиссия %</span></span><span class="math-denom">100</span></span></span></span></div></div></div></div></details><details class="faq-item"><summary>Как безопасно рассчитать максимальную скидку для клиента?</summary><div class="faq-content"><p>Максимальный размер скидки ограничен вашей валовой маржой. Скидка, равная марже, оставляет вас с нулём прибыли. Чтобы не работать в минус, максимальная допустимая скидка рассчитывается по формуле:</p><div class="formula-hero-card" style="margin:12px 0;"><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Скидка max %</span><span class="math-op">=</span><span class="math-var">Текущая маржа %</span><span class="math-op">−</span><span class="math-var">Минимальная маржа %</span></div></div></div><p>При марже 40% и желании сохранить хотя бы 15% чистой прибыли максимальная скидка не может превышать <strong>25%</strong>.</p></div></details><details class="faq-item"><summary>Нужно ли включать налог (самозанятость 4–6% или УСН 6%) в наценку?</summary><div class="faq-content"><p>Да, обязательно. Налог на профессиональный доход (самозанятые) и УСН «Доходы» начисляются со всей суммы выручки, поступающей на расчётный счёт или карту. Закладывайте налог в цену продажи поверх себестоимости, иначе налог будет съедать вашу личную оплату труда.</p></div></details></div><hr><h2 id="как-защитить-маржу-мастерскои-на-системном-уровне" tabindex="-1">Как защитить маржу мастерской на системном уровне <a class="header-anchor" href="#как-защитить-маржу-мастерскои-на-системном-уровне" aria-label="Permalink to &quot;Как защитить маржу мастерской на системном уровне&quot;">​</a></h2><p>Невозможно выстроить прибыльное ценообразование, если в фундаменте лежит неверная себестоимость: не оцифрованы обрезки сырья, не учтена ставка собственного рабочего часа или забыта амортизация оборудования.</p><div class="cta-grid"><div class="cta-card"><div class="cta-card-badge">Онлайн-инструмент</div><h3>Калькулятор себестоимости</h3><p>Мгновенный бесплатный расчёт затрат на материалы, обрезки, комплектующие и норма-час мастера с экспортом в Excel.</p><a href="/ru/calculators/product-cost-calculator" class="vp-button alt cta-icon-btn" data-omni-event="sat_pricing_cta_calc"><span>Рассчитать себестоимость онлайн</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div><div class="cta-card featured-cta"><div class="cta-card-badge brand-badge">Настольная программа</div><h3>«ОмниКрафт ЕРП» для Windows</h3><p>Профессиональный учёт мастерской: точные рецепты, автоматический пересчёт себестоимости по МАК, защита от продажи в минус и верстак без интернета.</p><a href="/ru/" class="vp-button brand cta-icon-btn" data-omni-event="sat_pricing_cta_home"><span>Узнать больше о программе</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div></div><hr><h2 id="связанные-статьи-производственного-кластера" tabindex="-1">Связанные статьи производственного кластера <a class="header-anchor" href="#связанные-статьи-производственного-кластера" aria-label="Permalink to &quot;Связанные статьи производственного кластера&quot;">​</a></h2><ul><li><a href="/ru/calculators/">Каталог онлайн-калькуляторов себестоимости «ОмниКрафт ЕРП»</a> — все специализированные отраслевые калькуляторы и готовые таблицы смет.</li><li><a href="/ru/articles/cost-calculation-software">Программы для расчёта себестоимости: почему Excel и 1С не подходят малым мастерским</a> — честный обзор учётных систем для растущего производства.</li><li><a href="/ru/calculators/product-cost-calculator">Универсальный калькулятор себестоимости продукции онлайн</a> — расчёт единицы товара, технологический брак и экспорт в Excel/LibreOffice.</li><li><a href="/ru/calculators/leather-cost-calculator">Калькулятор себестоимости изделия из кожи онлайн</a> — раскрой шкуры, топография деталей и финансовые ловушки мастерской.</li><li><a href="/ru/calculators/3d-print-cost-calculator">Калькулятор себестоимости 3D-печати онлайн</a> — расход филамента и фотополимера, амортизация принтера и норма-час оператора.</li><li><a href="/ru/calculators/cake-cost-calculator">Калькулятор себестоимости торта онлайн</a> — расчёт ингредиентов брутто, упёка, крема и декора для кондитеров.</li><li><a href="/ru/calculators/candle-cost-calculator">Калькулятор себестоимости свечей и диффузоров онлайн</a> — соевый воск, процент ввода ароматизатора, фитили и тара.</li><li><a href="/ru/calculators/dish-cost-calculator">Калькулятор себестоимости блюда и полуфабрикатов онлайн</a> — фудкост, уварка сырья брутто/нетто и упаковка для общепита.</li><li><a href="/ru/calculators/beauty-cost-calculator">Калькулятор себестоимости маникюра и бьюти-услуг онлайн</a> — одноразовые наборы, стерилизация по СанПиН и аренда кабинета.</li></ul>',11))])}const k=i(p,[["render",h]]);export{y as __pageData,k as default};
